options.onCreated:
const _this = this
async function getDocTypeList() {
  const masterTableDataTypeList = await $api.get('/docpal/case/types/dataType/mapping').then(res => res.data.data)
  const data = masterTableDataTypeList.map(item => ({
    label: $t(`marsterTable.type.${item.key}`),
    value: item.key
  }))
  return data
}
async function init() {
  const options = await getDocTypeList()
  _this.loadOptions(options)
}
init()

options.onChange:
const _this = this
const showList = {
  'volcaboury': [
    { key: 'vocabulary', isRequired: true },
  ],
  'master_table': [
    { key:'masterTable', isRequired: true },
    { key:'displayField', isRequired: true },
  ],
  'document': [
    { key: 'documentType', isRequired: true },
    { key: 'displayField', isRequired: true },
    // { key: 'isMultiple', isRequired: false }
  ]
}
function handleShow() {
  let showKeys = []
  Object.keys(showList).forEach(sKey => {
    showList[sKey].forEach(item => {
      if(!showKeys.includes(item.key)) setShow(item.key, sKey !== value, item.isRequired)
      if(sKey === value) {
        showKeys.push(item.key)
      }
    })
  })
}
function setShow(key, isHidden, isRequired) {
  const keyRef = _this.getWidgetRef(key)
  if(!keyRef) return
  isRequired = isHidden ? false : isRequired
  keyRef.setHidden(isHidden)
  keyRef.setRequired(isRequired)
}

handleShow()

