options.onMounted:
$api.get('/docpal/types/active', {}).then(res => {
   res = res.data.data
  const reponse = res.map(item => ({
    value: item.name,
    label: $t(item.name),
    keywords: item.keywords.map(kItem => ({ value: kItem.name, label: kItem.name }))
  }))
  reponse.sort((a, b) => a.label.localeCompare(b.label))
